transforms.code:
db = value["db"]
wkSelected = value["wkSelected"]
filterStatus = value["filterStatus"]

# ---------- Perspective: Button -> onActionPerformed ----------
logger = system.util.getLogger("WS-Check")
DATASOURCE = db  # <-- tu Data Source

def _normalize_ip(ip):
    if ip and ip.startswith("::ffff:"):
        return ip.split(":")[-1]
    return (ip or "").strip()

def _get_this_sessioninfo(self):
    sid = self.session.props.id
    for s in system.perspective.getSessionInfo():
        if s.get('id') == sid:
            return s
    return {}

try:
    sinfo = _get_this_sessioninfo(self)
    ip = _normalize_ip(sinfo.get('clientAddress',''))

    rows = system.db.runPrepQuery(
        "SELECT TOP 1 ID, [Description], Hostname FROM dbo.workstation WHERE IpAddress = ?",
        [ip], DATASOURCE
    )
    ws_id   = int(rows[0]['ID']) if rows else 0
    ws_desc = rows[0]['Description'] if rows else ''
    ws_host = rows[0]['Hostname'] if rows else ''

    #logger.info("Button check -> IP=%s  WSID=%s  Desc=%s  Host=%s" % (ip, ws_id, ws_desc, ws_host))

except Exception as e:
    logger.error("Button check error: %s" % e)


if filterStatus:
	idValue = wkSelected
else:
	idValue = ws_id
return idValue

